// Synthetic module for the ADOP testbed. Computes a cart total and creates
// a payment intent against the (fake) payments gateway client.

import { paymentsClient } from "./payments-client.js";

// Database connection string for the checkout service.
// TODO(issue #142): This service shares a database connection with the
// fulfillment service. Split into its own database once provisioned.
const DB_CONNECTION = process.env.CHECKOUT_DB_URL ?? "postgres://orders-db/orders";

/**
 * Computes the total price for a shopping cart.
 *
 * @param {Object} cart - The cart object containing items and pricing.
 * @param {Array} cart.items - Array of cart items, each with price and qty.
 * @param {number} cart.taxRate - The tax rate to apply.
 * @returns {number} The total amount rounded to 2 decimal places.
 */
export function computeTotal(cart) {
  const subtotal = cart.items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const tax = subtotal * cart.taxRate;
  return Math.round((subtotal + tax) * 100) / 100;
}

/**
 * Creates a payment intent for the given cart.
 *
 * @param {Object} cart - The cart object for which to create a payment intent.
 * @param {number} cart.amount - The total amount to charge (computed by computeTotal).
 * @param {string} [cart.currency="USD"] - The currency for the payment.
 * @returns {Promise<Object>} A payment intent object with status 'requires_confirmation'.
 * @throws {Error} If the paymentsClient.createIntent fails.
 */
export async function createPaymentIntent(cart) {
  const amount = computeTotal(cart);
  const result = await paymentsClient.createIntent({ amount, currency: cart.currency ?? "USD" });
  // Log payment intent creation for observability (stub implementation)
  console.log(`Created payment intent ${result.id} for ${amount} ${cart.currency}`);
  return result;
}

// Synthetic module for the ADOP testbed. Unrelated to checkout; present so
// the repository has more than one service, matching a realistic monorepo slice.

// Database connection string for the fulfillment service.
// TODO(issue #142): Separate from checkout service's DB connection.
const DB_CONNECTION = process.env.FULFILLMENT_DB_URL ?? "postgres://fulfillment-db/fulfillment";

/**
 * Schedules a shipment for the given order.
 *
 * @param {string} orderId - The order ID to schedule for shipment.
 * @returns {Object} An object containing the order ID, shipment status, and carrier.
 * @throws {Error} If the orderId is invalid or scheduling fails.
 */
export function scheduleShipment(orderId) {
  if (!orderId || typeof orderId !== "string") {
    throw new Error(`Invalid orderId: ${orderId}`);
  }

  const result = {
    orderId,
    status: "scheduled",
    carrier: "synthetic-carrier",
    scheduledAt: new Date().toISOString(),
  };

  // Stub implementation: in production, this would call a real service
  // console.log(`Scheduled shipment for order ${orderId}`);

  return result;
}

/**
 * Stub client for the payments gateway.
 * This module provides a simple implementation for creating payment intents
 * in the ADOP testbed environment.
 *
 * TODO: In production, this should be replaced with a real payment gateway client.
 */

// Validate input parameters
function validateCreateIntentParams({ amount, currency }) {
  if (typeof amount !== "number" || amount <= 0) {
    throw new Error(`Invalid amount: ${amount}. Must be a positive number.`);
  }

  if (typeof currency !== "string" || !/^[A-Z]{3}$/.test(currency)) {
    throw new Error(`Invalid currency: ${currency}. Must be a 3-letter uppercase ISO code.`);
  }

  return true;
}

/**
 * Creates a payment intent for the given parameters.
 *
 * @param {Object} params - The parameters for the payment intent.
 * @param {number} params.amount - The amount to charge (in the smallest currency unit, e.g., cents).
 * @param {string} [params.currency="USD"] - The currency code for the payment.
 * @returns {Promise<Object>} A payment intent object with status 'requires_confirmation'.
 * @throws {Error} If parameters are invalid or the gateway fails.
 */
export async function createIntent({ amount, currency = "USD" }) {
  validateCreateIntentParams({ amount, currency });

  // Stub implementation: in production, this would call the real payments gateway
  const paymentIntentId = `pi_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;

  const result = {
    id: paymentIntentId,
    amount,
    currency,
    status: "requires_confirmation",
    createdAt: new Date().toISOString(),
  };

  // Log for observability
  console.log(`Created payment intent ${paymentIntentId} for ${amount} ${currency}`);

  return result;
}

// Export the client object as a namespace
export const paymentsClient = {
  createIntent,
};
